<script setup lang="ts">
import {ref} from 'vue'
import {Music2,ArrowUpRight,Plus} from 'lucide-vue-next'
import {user,profile} from '../lib/session'
import {db,fail,friendly} from '../lib/supabase'
defineProps<{playlist:string}>();const emit=defineEmits<{login:[]}>()
const title=ref(''),artist=ref(''),url=ref(''),busy=ref(false),error=ref(''),message=ref('')
async function submit(){if(!user.value){emit('login');return}error.value='';message.value='';if(!profile.value){error.value='Completa tu perfil en Mi invitación antes de proponer canciones.';return}busy.value=true;try{let normalized='';if(url.value.trim()){const u=new URL(url.value);if(u.hostname!=='open.spotify.com'||!/^\/track\/[A-Za-z0-9]{22}$/.test(u.pathname))throw new Error('Pega un enlace de canción de open.spotify.com/track/…');normalized='https://open.spotify.com'+u.pathname}const {error:e}=await db.from('wedding_songs').insert({user_id:user.value.id,title:title.value.trim(),artist:artist.value.trim(),spotify_url:normalized});fail(e);message.value='¡Propuesta recibida! Los novios la revisarán para la playlist.';title.value='';artist.value='';url.value=''}catch(e){error.value=friendly(e)}finally{busy.value=false}}
function validPlaylist(value:string){return /^https:\/\/open\.spotify\.com\/playlist\/[A-Za-z0-9]+/.test(value)}
</script>
<template><section id="musica" class="music-section section"><div class="music-copy"><span class="eyebrow">LA BANDA SONORA DE NUESTRO DÍA</span><h2>Esta canción<br/><em>es muy nuestra.</em></h2><p>Esa que siempre cantamos. La que nos hace levantarnos de la silla. Ayúdanos a llenar la pista de buenos recuerdos.</p><a v-if="validPlaylist(playlist)" :href="playlist" target="_blank" rel="noopener noreferrer" class="text-link">Escuchar la playlist <ArrowUpRight :size="18"/></a><p v-else class="small muted">Muy pronto compartiremos la playlist de la boda.</p><div class="vinyl" aria-hidden="true"><div><Music2 :size="31"/><span>L & J</span></div></div></div><form class="song-form" @submit.prevent="submit"><Music2 :size="26"/><h3>¿Cuál no puede faltar?</h3><label>Canción<input v-model="title" required maxlength="150" placeholder="El título de ese temazo"/></label><label>Artista<input v-model="artist" required maxlength="150" placeholder="¿Quién lo canta?"/></label><label>Enlace de Spotify <span class="muted">opcional</span><input v-model="url" type="url" placeholder="https://open.spotify.com/track/…"/></label><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><button class="btn full" :disabled="busy"><Plus :size="17"/>{{busy?'Enviando…':user?'Proponer canción':'Entrar para proponer'}}</button><p class="small muted">Guardaremos tu propuesta para que los novios la añadan a la fiesta.</p></form></section></template>
